auto recursive_step = [](auto self, FunctionPtr f, double a, double b, double fa, double fb, double whole, double precision) -> double {
    double mid = (a + b) / 2.0;
    double fmid = f(mid);
    double left = (fa + fmid) * (mid - a) / 2.0;
    double right = (fmid + fb) * (b - mid) / 2.0;
    if (std::abs(left + right - whole) <= 3.0 * precision) {
        return left + right + (left + right - whole) / 3.0;
    }
    return self(self, f, a, mid, fa, fmid, left, precision / 2.0) + 
           self(self, f, mid, b, fmid, fb, right, precision / 2.0);
};

double fa = f(a);
double fb = f(b);
double whole = (fa + fb) * (b - a) / 2.0;
return recursive_step(recursive_step, f, a, b, fa, fb, whole, precision);
// END_CODE

